	/** 
	 * jumpstart the process by instantiating2 Contact
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		contactId = ContactService.getContactInstance()
		.createContact( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ContactService.getContactInstance()
				.createContact( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.contactSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Contact : " + successValue.getContactId());
							  if (successValue.getContactId().equals(contactId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfContactList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Contact test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on contact consumed")
					);
			subscriber.contactSubscribe( contactId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Contact : " + successValue.getContactId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfContactList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on contact for contactId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Contact. 
	 */
	protected Contact read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Contact" );

		Contact entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Contact with primary key" );
		msg.append( contactId );
		
		ContactFetchOneSummary fetchOneSummary = new ContactFetchOneSummary( contactId );

		try {
			entity = ContactService.getContactInstance().getContact( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Contact " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Contact.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Contact." );

		StringBuilder msg = new StringBuilder( "Failed to update a Contact : " );        
		Contact entity = read();
		UpdateContactCommand command = generateUpdateCommand();
		command.setContactId(entity.getContactId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Contact." );

			// for use later on...
			contactId = entity.getContactId();

			ContactService proxy = ContactService.getContactInstance();  

			proxy.updateContact( command ).get();

			LOGGER.info( "-- Successfully saved Contact - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + contactId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Contact.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Contact." );

		Contact entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Contact with id " + contactId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Contact with id " + contactId );

			throw e;
		}

		try{
			ContactService.getContactInstance().delete( new DeleteContactCommand( entity.getContactId() ) ).get();
			LOGGER.info( "-- Successfully deleted Contact with id " + contactId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Contact with id " + contactId );

			throw e;
		}
	}

	/**
	 * get all Contacts.
	 */
	protected List<Contact> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Contacts:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Contact : " );        
		List<Contact> collection  = new ArrayList<>();

		try {
			// call the static get method on the ContactService
			collection = ContactService.getContactInstance().getAllContact();
			assertNotNull( collection, "An Empty collection of Contact was incorrectly returned.");
			
			// Now print out the values
			Contact entity = null;            
			Iterator<Contact> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getContactId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

